import {Vector3} from 'three';
export function eqsDebugPage(snapshot,{offset=0,limit=64,failed=true}={}){
 if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256||typeof failed!=='boolean')throw Error('EQS 진단 페이지를 확인하세요.');
 if(!snapshot)return {ready:false,total:0,items:[]};const {items,...summary}=snapshot,rows=failed?items:items.filter(i=>i.matched);return {ready:true,...structuredClone(summary),total:rows.length,offset,items:structuredClone(rows.slice(offset,offset+limit))};
}
export class EqsDebugOverlay{
 constructor(canvas){this.canvas=canvas;this.element=canvas.ownerDocument.createElement('div');this.element.className='eqs-debug-overlay';canvas.parentElement.append(this.element);this.point=new Vector3();this.labels=true;this.failed=true;this.snapshot=null;this.next=0;this.drawn=0;}
 set(snapshot,{labels=this.labels,failed=this.failed}={}){if(typeof labels!=='boolean'||typeof failed!=='boolean')throw Error('EQS 보기 옵션을 확인하세요.');this.snapshot=snapshot;this.labels=labels;this.failed=failed;this.next=0;this.element.replaceChildren();const items=(snapshot?.items||[]).filter(i=>failed||i.matched).sort((a,b)=>Number(b.matched)-Number(a.matched)||(a.rank??a.id)-(b.rank??b.id)).slice(0,512);let min=Infinity,max=-Infinity;for(const i of items)if(i.matched){min=Math.min(min,i.score);max=Math.max(max,i.score);}for(const i of items){const marker=this.canvas.ownerDocument.createElement('span');marker.className='eqs-debug-point'+(i.matched?'':' failed');const score=max===min?1:(i.score-min)/(max-min),color=i.matched?'hsl('+Math.round(score*120)+' 65% 55%)':'#6497ed';marker.style.setProperty('--eqs-color',color);if(labels){const text=this.canvas.ownerDocument.createElement('small');text.textContent=i.matched?Number(i.score.toPrecision(4)).toString():'×'+(i.failedTest==='projection'?'투영':i.failedTest+1);marker.append(text);marker.label=text;}marker.title=(i.actor||'#'+i.id)+(i.matched?' · '+i.score:' · 실패 '+i.failedTest);this.element.append(marker);marker.item=i;}this.items=items;}
 draw(camera,now=performance.now()){if(now<this.next)return;this.next=now+100;const r=this.canvas.getBoundingClientRect(),parent=this.element.parentElement.getBoundingClientRect();this.element.style.left=r.left-parent.left+'px';this.element.style.top=r.top-parent.top+'px';this.element.style.width=r.width+'px';this.element.style.height=r.height+'px';this.drawn=0;this.labelsDrawn=0;const labels=[];camera.updateWorldMatrix(true,false);for(const m of this.element.children){const p=this.point.fromArray(m.item.position).project(camera),shown=p.z>=-1&&p.z<=1&&Math.abs(p.x)<=1&&Math.abs(p.y)<=1;m.hidden=!shown;if(shown){const x=(p.x*.5+.5)*r.width,y=(-p.y*.5+.5)*r.height;m.style.transform='translate('+x+'px,'+y+'px)';this.drawn++;if(m.label){const box={x:x+8,y:y-3,width:m.label.textContent.length*7+5,height:17},overlap=labels.length>=64||labels.some(b=>box.x<b.x+b.width&&box.x+box.width>b.x&&box.y<b.y+b.height&&box.y+box.height>b.y);m.label.hidden=overlap;if(!overlap){labels.push(box);this.labelsDrawn++;}} }}}
 inspect(){return {enabled:!!this.snapshot,markers:this.items?.length||0,drawn:this.drawn,labelsDrawn:this.labelsDrawn||0,labelLimit:64,labels:this.labels,failed:this.failed,displayLimit:512};}
 dispose(){this.element.remove();this.snapshot=null;this.items=[];}
}
